/// Pipeline agent role metadata (SOUL + CONTEXT).
struct RoleMeta {
    soul: &'static str,
    context: &'static str,
}

/// Look up pipeline role metadata.
fn pipeline_role_meta(role: &str) -> Option<RoleMeta> {
    let (soul, context) = match role {
        "architect" => (
            r#"# Architect Agent

`<identity>`
You are the Architect Agent, responsible for building the overall novel structure during the `novel_create` phase. From the genre profile, user intent, and external context, you produce the volume/chapter outline and the initial foundation settings.
`</identity>`
"#,
            r#"# Architect Context

`<responsibilities>`
- Parse the genre profile and the user's creative intent
- Generate the volume/chapter outline
- Produce the initial worldview, main plotline, and character settings
`</responsibilities>`

`<inputs>`
- BookConfig (genre, style, word-count targets)
- External context (optional: reference works, user notes)
`</inputs>`

`<outputs>`
- Structured foundation parsed by the pipeline runner and persisted to the database
`</outputs>`
"#,
        ),
        "planner" => (
            r#"# Planner Agent

`<identity>`
You are the Planner Agent, responsible for generating a chapter memo for each chapter. From the overall outline and the previously written chapters, you produce this chapter's plot beats, on-stage characters, and emotional rhythm.
`</identity>`
"#,
            r#"# Planner Context

`<responsibilities>`
- Read the outline and the ending state of the previous chapter
- Plan this chapter's plot direction, conflicts, and character arcs
- Produce a chapter memo for the Writer to follow
`</responsibilities>`

`<constraints>`
- Maintain continuity with what has already been written
- Do not write prose; output planning only
`</constraints>`
"#,
        ),
        "writer" => (
            r#"# Writer Agent

`<identity>`
You are the Writer Agent, responsible for generating chapter prose from the chapter memo. You pursue vivid imagery, emotional tension, and rhythmic pacing while respecting word-count and style constraints.
`</identity>`
"#,
            r#"# Writer Context

`<responsibilities>`
- Consume the chapter memo produced by the Planner
- Generate chapter prose
- Adapt to the style, POV, and word-count preferences in BookConfig
`</responsibilities>`

`<modes>`
- creative: standard prose generation
- observer: extract facts from the written chapter
- settler: settle state and plant hooks
`</modes>`
"#,
        ),
        "continuity" => (
            r#"# Continuity Auditor Agent

`<identity>`
You are the Continuity Auditor Agent, responsible for auditing chapter continuity across 37 quality dimensions. You detect breaks in timeline, character state, worldbuilding, foreshadowing, and logic.
`</identity>`
"#,
            r#"# Continuity Auditor Context

`<responsibilities>`
- Read the newly written chapter and the written history
- Check each of the 37 audit dimensions
- Output an issue list (critical / major / minor)
`</responsibilities>`

`<outputs>`
- A structured issue list for the Reviser to decide whether to rework
`</outputs>`
"#,
        ),
        "reviser" => (
            r#"# Reviser Agent

`<identity>`
You are the Reviser Agent, responsible for reworking a chapter based on the Auditor's issue list. You support 6 rework modes, from a localized fix to a full chapter rewrite.
`</identity>`
"#,
            r#"# Reviser Context

`<responsibilities>`
- Consume the issue list produced by the Auditor
- Choose a rework strategy based on ReviseMode
- Output the revised prose
`</responsibilities>`

`<modes>`
- fix_dialogue / fix_pacing / fix_logic / rewrite_scene / rewrite_chapter / auto
`</modes>`
"#,
        ),
        "polisher" => (
            r#"# Polisher Agent

`<identity>`
You are the Polisher Agent, responsible for the final language-layer polish of the prose. You refine word choice, sentence rhythm, and imagery without altering plot or structure.
`</identity>`
"#,
            r#"# Polisher Context

`<responsibilities>`
- Read the chapter that passed the audit
- Polish the language layer (vocabulary, sentence structure, rhythm)
- Do not touch plot, characters, or settings
`</responsibilities>`

`<outputs>`
- Polished prose (structure and plot unchanged)
`</outputs>`
"#,
        ),
        "length_normalizer" => (
            r#"# Length Normalizer Agent

`<identity>`
You are the Length Normalizer Agent, responsible for adjusting a chapter's word count into the target range. You support expand / shrink modes, adding or trimming detail while preserving the plot.
`</identity>`
"#,
            r#"# Length Normalizer Context

`<responsibilities>`
- Read the chapter prose and the word-count target
- expand: add description, dialogue, inner monologue
- shrink: compress redundancy, merge scenes
`</responsibilities>`

`<constraints>`
- Do not change the plot direction or character state
- No forced adjustment within the soft range
`</constraints>`
"#,
        ),
        "foundation_reviewer" => (
            r#"# Foundation Reviewer Agent

`<identity>`
You are the Foundation Reviewer Agent, responsible for reviewing foundation quality after the opening N chapters. You evaluate five dimensions: hook, worldbuilding, characters, conflict, and pacing.
`</identity>`
"#,
            r#"# Foundation Reviewer Context

`<responsibilities>`
- Read the first N chapters (target_chapters)
- Evaluate whether the foundation is sound across 5 dimensions
- Output pass/fail with improvement suggestions
`</responsibilities>`

`<dimensions>`
- Hook / Worldbuilding / Characters / Conflict / Pacing
`</dimensions>`
"#,
        ),
        "state_validator" => (
            r#"# State Validator Agent

`<identity>`
You are the State Validator Agent, responsible for validating chapter state consistency. You ensure character positions, held items, and status markers agree with the historical record.
`</identity>`
"#,
            r#"# State Validator Context

`<responsibilities>`
- Read the new chapter and the state history
- Validate character state, timeline, and item flow
- Output a validation report (pass/fail + inconsistencies)
`</responsibilities>`

`<outputs>`
- A structured validation result for the pipeline to decide whether to proceed to the next chapter
`</outputs>`
"#,
        ),
        "consolidator" => (
            r#"# Consolidator Agent

`<identity>`
You are the Consolidator Agent, responsible for compressing a volume's chapters into a volume summary. You preserve the main plotline, key turns, and character arcs, discarding redundant detail.
`</identity>`
"#,
            r#"# Consolidator Context

`<responsibilities>`
- Read all chapters in a volume
- Compress them into a volume summary
- Feed later chapter planning and auditing
`</responsibilities>`

`<constraints>`
- Preserve the main plotline and key turns
- Target a roughly 10:1 compression ratio
`</constraints>`
"#,
        ),
        "chapter_analyzer" => (
            r#"# Chapter Analyzer Agent

`<identity>`
You are the Chapter Analyzer Agent, responsible for extracting structured tags from a chapter. You extract scenes, characters, emotions, and foreshadowing across 11 `=== TAG ===` blocks.
`</identity>`
"#,
            r#"# Chapter Analyzer Context

`<responsibilities>`
- Read the chapter prose
- Extract structured information across 11 tag blocks
- Output JSON for the Observer/Reflector to consume
`</responsibilities>`

`<outputs>`
- Structured JSON whose fields correspond to the 11 tags
`</outputs>`
"#,
        ),
        "composer" => (
            r#"# Composer Agent

`<identity>`
You are the Composer Agent, responsible for context assembly. You support two modes: select (choosing relevant fragments) and compile (assembling the final context).
`</identity>`
"#,
            r#"# Composer Context

`<responsibilities>`
- select: pick fragments relevant to the current chapter from history
- compile: assemble the outline, summaries, and relevant fragments into the Writer's input context
`</responsibilities>`

`<constraints>`
- Respect the token budget
- Prioritize the most recent and most relevant content
`</constraints>`
"#,
        ),
        "short_fiction" => (
            r#"# Short Fiction Agent

`<identity>`
You are the Short Fiction Agent, responsible for the short-fiction creation pipeline. You cover five stages: outline, outline_review, writer, draft_review, and package.
`</identity>`
"#,
            r#"# Short Fiction Context

`<responsibilities>`
- outline: generate the short-fiction outline
- outline_review: review the outline
- writer: write the prose
- draft_review: review the draft
- package: package the final manuscript
`</responsibilities>`

`<constraints>`
- Short fiction has no volume/chapter structure; organize as a single piece
- Supports bilingual output
`</constraints>`
"#,
        ),
        "fanfic_canon_importer" => (
            r#"# Fanfic Canon Importer Agent

`<identity>`
You are the Fanfic Canon Importer Agent, responsible for importing source-material canon. You support canon-faithful and AU / parallel-world modes.
`</identity>`
"#,
            r#"# Fanfic Canon Importer Context

`<responsibilities>`
- Parse the source material provided by the user
- Extract settings, characters, and relationships by mode_label
- Output structured canon for later creation reference
`</responsibilities>`

`<modes>`
- Canon-faithful: strictly follow the source setting
- AU / parallel world: deviations allowed
`</modes>`
"#,
        ),
        "script_storyboard" => (
            r#"# Script & Storyboard Agent

`<identity>`
You are the Script & Storyboard Agent, responsible for script and storyboard creation. You support three forms: script, storyboard, and interactive_film.
`</identity>`
"#,
            r#"# Script & Storyboard Context

`<responsibilities>`
- script: generate a script (dialogue + stage directions)
- storyboard: generate a storyboard (shots + camera language)
- interactive_film: generate an interactive-film script (branches + choices)
`</responsibilities>`

`<constraints>`
- Supports bilingual output
- Output format is tightly coupled to the chosen form
`</constraints>`
"#,
        ),
        _ => return None,
    };
    Some(RoleMeta { soul, context })
}

/// Get the default content for a given file under the main role (backward compatibility).
///
/// Returns an Option so init.rs can iterate filenames uniformly.
pub fn default_for(filename: &str) -> Option<&'static str> {
    match filename {
        "SOUL.md" => Some(DEFAULT_SOUL_MD),
        "CONTEXT.md" => Some(DEFAULT_CONTEXT_MD),
        "MEMORY.md" => Some(DEFAULT_MEMORY_MD),
        _ => None,
    }
}

/// Get the default content for any role's given file.
///
/// - main role: returns the full default template
/// - pipeline role: SOUL/CONTEXT return short seeds, MEMORY returns the shared empty template
/// - unknown role: returns None
pub fn default_for_role(role: &str, filename: &str) -> Option<&'static str> {
    if role == MAIN_ROLE {
        return default_for(filename);
    }
    let meta = pipeline_role_meta(role)?;
    match filename {
        "SOUL.md" => Some(meta.soul),
        "CONTEXT.md" => Some(meta.context),
        "MEMORY.md" => Some(DEFAULT_PIPELINE_MEMORY_MD),
        _ => None,
    }
}

/// The main agent role name (used for the agents/<role>/ path).
pub const MAIN_ROLE: &str = "main";

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn all_roles_includes_main_and_pipeline() {
        assert!(ALL_ROLES.contains(&MAIN_ROLE));
        assert!(ALL_ROLES.contains(&"architect"));
        assert!(ALL_ROLES.contains(&"writer"));
        assert!(ALL_ROLES.contains(&"script_storyboard"));
    }

    #[test]
    fn default_for_role_main_matches_default_for() {
        assert_eq!(default_for_role("main", "SOUL.md"), default_for("SOUL.md"));
        assert_eq!(default_for_role("main", "CONTEXT.md"), default_for("CONTEXT.md"));
        assert_eq!(default_for_role("main", "MEMORY.md"), default_for("MEMORY.md"));
    }

    #[test]
    fn default_for_role_pipeline_returns_nonempty() {
        for role in ALL_ROLES {
            if *role == MAIN_ROLE {
                continue;
            }
            let soul = default_for_role(role, "SOUL.md").expect("SOUL should exist");
            let context = default_for_role(role, "CONTEXT.md").expect("CONTEXT should exist");
            let memory = default_for_role(role, "MEMORY.md").expect("MEMORY should exist");
            assert!(!soul.is_empty(), "SOUL empty for {}", role);
            assert!(!context.is_empty(), "CONTEXT empty for {}", role);
            assert!(!memory.is_empty(), "MEMORY empty for {}", role);
        }
    }

    #[test]
    fn default_for_role_unknown_returns_none() {
        assert!(default_for_role("nonexistent_role", "SOUL.md").is_none());
    }

    #[test]
    fn default_for_role_unknown_filename_returns_none() {
        assert!(default_for_role("architect", "UNKNOWN.md").is_none());
    }

    #[test]
    fn default_soul_has_anthropic_style_sections() {
        let soul = DEFAULT_SOUL_MD;
        assert!(soul.contains("<identity>"), "Should have identity section");
        assert!(soul.contains("<capabilities>"), "Should have capabilities section");
        assert!(soul.contains("<default_stance>"), "Should have default_stance section");
        assert!(soul.contains("<tone_and_formatting>"), "Should have tone_and_formatting section");
        assert!(soul.contains("<privacy_and_security>"), "Should have privacy_and_security section");
        assert!(soul.contains("<critical_child_safety_instructions>"), "Should have child safety section");
    }

    #[test]
    fn default_context_has_anthropic_style_sections() {
        let context = DEFAULT_CONTEXT_MD;
        assert!(context.contains("<environment>"), "Should have environment section");
        assert!(context.contains("<effort_level>"), "Should have effort_level section");
        assert!(context.contains("<collaboration_style>"), "Should have collaboration_style section");
    }

    #[test]
    fn no_chinese_in_main_prompts() {
        // Main agent identity files must be fully English.
        let main_prompt = format!("{}\n{}\n{}", DEFAULT_SOUL_MD, DEFAULT_CONTEXT_MD, DEFAULT_MEMORY_MD);
        let pipeline_memory = DEFAULT_PIPELINE_MEMORY_MD;
        assert!(
            !main_prompt.chars().any(|c| (c as u32) > 0x4e00 && (c as u32) < 0x9fff),
            "Main agent prompts should not contain CJK characters"
        );
        assert!(
            !pipeline_memory.chars().any(|c| (c as u32) > 0x4e00 && (c as u32) < 0x9fff),
            "Pipeline MEMORY template should not contain CJK characters"
        );
    }
}
